function FeaturedResidences() {
  const { data, loading } = useData(async () => {
    const all = await db.publishedProperties({ listing_type: 'sale' })
    return all.filter((p) => p.featured).concat(all.filter((p) => !p.featured)).slice(0, 3)
  }, [], [])
  if (loading) return <div className="grid grid-cols-1 md:grid-cols-3 gap-gutter-desktop">{[0, 1, 2].map((i) => <div key={i} className="aspect-[4/3] rounded-lg bg-surface-container-high animate-pulse" />)}</div>
  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-gutter-desktop">
      {data.map((p) => (
        <Link key={p.id} to={`/properties/${p.slug}`} className="block">
          <article className="group flex flex-col">
            <div className="relative aspect-[4/3] w-full overflow-hidden rounded-lg bg-surface-container-high mb-6" data-cursor="View">
              <img alt={p.title} className="w-full h-full object-cover transition-transform duration-700 ease-out group-hover:scale-105" src={p.cover_image} loading="lazy" />
              <div className="absolute top-4 left-4 bg-surface/90 backdrop-blur-sm px-3 py-1 rounded-full"><span className="font-label-caps text-label-caps uppercase tracking-wider text-primary">{[p.city, p.region].filter(Boolean).join(', ')}</span></div>
            </div>
            <div className="space-y-2">
              <h3 className="font-headline-sm text-headline-sm font-medium text-on-surface group-hover:text-secondary transition-colors">{p.title.split(' — ')[0]}</h3>
              <p className="font-label-caps text-label-caps uppercase tracking-wider text-outline">{p.bedrooms} Bedrooms · {p.bathrooms} Bathrooms · {sqft(p.area_sqft)}</p>
              <div className="pt-3"><span className="inline-flex items-center gap-1.5 font-label-caps text-label-caps uppercase tracking-[0.14em] text-primary group-hover:text-secondary transition-colors">Explore Residence <span className="material-symbols-outlined text-[14px] transition-transform duration-300 group-hover:translate-x-1">arrow_forward</span></span></div>
            </div>
          </article>
        </Link>
      ))}
    </div>
  )
}

